    # ========= UTILS =========

    @staticmethod
    def _get_iterator_for_device_endpoint(endpoints, number_of_devices, strategy):
        if strategy == "round_robin":
            return list(islice(cycle(endpoints), number_of_devices))

        # strategy == "blocks", by default
        n_endpoints = len(endpoints)
        block_size = number_of_devices // n_endpoints
        remainder = number_of_devices % n_endpoints
        result = []
        idx = 0
        for i, ep in enumerate(endpoints):
            size = block_size + (1 if i < remainder else 0)
            result.extend([ep] * size)
            idx += size
        return result

    def _get_du_alias_list(self, alias_list):
        return [alias for alias in alias_list if "du" in alias]

    def _get_object_attributes_noexcept(self, object_name, /, silent=False):
        """
        Wrapper for ta_emss.get_object_attributes as it returns exception if object does not exist.
        Returns params as a dict, or empty dict if fetching was not successful.
        """
        attrs = {}
        if not silent:
            self._log_print("Fetching attributes from object={}.".format(object_name))
        try:
            attrs = self.get_object_attributes(object_name=object_name, silent=True, alias=self.alias)
        except AssertionError:
            if not silent:
                self._log_print("Fetching attributes failed for object={}.".format(object_name))
        return attrs

    def _get_sorted_existing_objects_of_given_type(self, type_of_objects, /, reverse=False, silent=False, alias=None):
        """Wrapper on get_existing_objects_of_given_type, that return objects in proper sorting order"""
        alias = alias or self.alias
        objects = sorted(
            self.get_existing_objects_of_given_type(type_of_objects=type_of_objects, silent=True, alias=alias),
            key=self._sorting_key,
            reverse=reverse,
        )
        if not silent and objects == []:
            self._log_print(f"No {type_of_objects} object has been found.")
        return objects

    def _maybe_get_telemetry_params(self, ex_terminator_options):
        try:
            if self._is_package_installed("emssim") and self.emssim:
                ret = self.run_emssim_command("bts_get", params="-BUILD_ID", get_full_data=True)
                # [{'attr': '-BUILD_ID', 'msg': 'Attr value', 'value': 'vCUCNF26R1_0.250.31850'}, {'result': 1}]
                for item in ret:
                    if item.get("attr") == "-BUILD_ID":
                        build = item.get("value", "unknown")
                        self._log_print(f"BTS Build fetched from emssim: {build}")
                        ex_terminator_options["bts_build"] = build
            ta_emss_build = version("ta_emss")
            ex_terminator_options["ta_emss_build"] = ta_emss_build
        except Exception:
            self._log_debug("Unable to fetch BTS and/or ta_emss build version.")

    def _setup_logger(self):
        logger = logging.getLogger(__name__)
        logger.setLevel(logging.DEBUG)

        current_time = datetime.now().strftime("%Y%m%d_%H%M%S")
        log_filename = f"LOG-DYNAMIC-SETUP-{current_time}.log"
        log_file = os.path.join(self._db.get_logdir(), log_filename)
        file_handler = logging.FileHandler(log_file)
        file_handler.setLevel(logging.DEBUG)

        console_handler = logging.StreamHandler()
        console_handler_level = logging.INFO
        console_handler.setLevel(console_handler_level)

        formatter = logging.Formatter("[%(asctime)s.%(msecs)03d] %(message)s", datefmt="%H:%M:%S")

        file_handler.setFormatter(formatter)
        console_handler.setFormatter(formatter)

        if not logger.handlers:
            logger.addHandler(file_handler)
            logger.addHandler(console_handler)

        return logger

    def _log_debug(self, msg):
        if self.dynamic_logger:
            self.dynamic_logger.debug(msg)

    def _log_print(self, msg):
        if self.dynamic_logger:
            self.dynamic_logger.info(msg)

    def _print_divider(self, message="", width=60):
        if message:
            padding = (width - len(message) - 2) // 2
            self._log_print(f"{'=' * padding} {message} {'=' * padding}")
        else:
            self._log_print("=" * (width - 1))

    @staticmethod
    def _format_snssai(sst, sd):
        sst_val = hex(int(sst)).lstrip("0x").upper()
        sd_val = hex(int(sd)).lstrip("0x").upper()
        return f"{sst_val:0>2}:{sd_val}"

    @staticmethod
    def _get_plmn(attrs, mcc_key="mcc", mnc_key="mnc", mnc_length_key="mnc_length"):
        mcc = attrs[mcc_key]
        mnc_length = int(attrs.get(mnc_length_key, 2))
        mnc = attrs[mnc_key]
        formatted_mnc = f"{mnc:0>{mnc_length}}"
        return mcc, formatted_mnc

    @staticmethod
    def _sorting_key(string, /):
        """Sorting key for alphanumeric strings"""
        return "".join([format(int(x), "05d") if x.isdigit() else x for x in re.split(r"(\d+)", string)])

    def _get_interface_dn_ipaddres_tnl_id_and_prefix_length(self, ip_addr, ipv4_dn_ipaddress, ipv6_dn_ipaddress):
        ip_addr_version = ip_address(ip_addr).version

        if ip_addr_version == 4:
            if ipv4_dn_ipaddress is None:
                print(f"For the specified {ip_addr}, whose address is IPv4, the corresponding ipV4AddressDN1 was not read."
                      f" The object with this IP will be skipped when adding IPSEC objects.")
                return None, None, None
            dn_ipaddress = ipv4_dn_ipaddress
            tnl_id = re.search(r'TNL-(\d+)', dn_ipaddress).group(1)
            prefix_length = '32'
            return dn_ipaddress, tnl_id, prefix_length

        elif ip_addr_version == 6:
            if ipv6_dn_ipaddress is None:
                print(f"For the specified {ip_addr}, whose address is IPv6, the corresponding ipV6AddressDN1 was not read."
                      f"The object with this IP will be skipped when adding IPSEC objects")
                return None, None, None
            dn_ipaddress = ipv6_dn_ipaddress
            tnl_id = re.search(r'TNL-(\d+)', dn_ipaddress).group(1)
            prefix_length = '128'
            return dn_ipaddress, tnl_id, prefix_length
        return None

    def _add_ipsec_config_amf_sim(self):
        configure_ipsec_mocs_command = []
        for amf in self._db.amfs:
            configure_ipsec_mocs_command.append({'MOC': 'SECPOL', 'ID': f'1-2-1-1-{self.current_secpol_id}',
                                                 'ipSecAction': 'BYPASS',
                                                 'policyOrderNumber': f'100{amf["AMF_REGION_ID"]}',
                                                 'trafficSelectorList': [{'localIpAddress': amf["AMF_IP_FAREND"],
                                                                          'localIpPrefixLength': '32',
                                                                          'remoteIpAddress': amf["AMF_IP_ADDR"],
                                                                          'remoteIpPrefixLength': '32'
                                                                          }]
                                                 })
            self.current_secpol_id += 1
        return configure_ipsec_mocs_command

    def _add_ipsec_config_gnb_sim(self, establishment_mode):
        ipv4_xnc_dn_ipaddress, ipv6_xnc_dn_ipaddress = self._get_ipv4_and_ipv6_address_dn1_for_link_type('xnc', alias=self.alias)
        configure_ipsec_mocs_command = []
        for gnb in self._db.gnbs:
            dn_ipaddress, tnl_id, prefix_length = self._get_interface_dn_ipaddres_tnl_id_and_prefix_length(gnb['IP_ADDR'], ipv4_xnc_dn_ipaddress, ipv6_xnc_dn_ipaddress)
            if dn_ipaddress is None:
                continue
            configure_ipsec_mocs_command.append({'MOC': 'IPAPP', 'ID': '1-2-1'})
            configure_ipsec_mocs_command.append({'MOC': 'IPSECC', 'ID': '1-2-1-1',
                                                 'authenticationScheme': 'PSK',
                                                 'ipSecEnabled': 'true'})
            configure_ipsec_mocs_command.append({'MOC': 'IPSECP', 'ID': '1-2-1-1-1',
                                                 'antiReplayWindowSize': 'SIZE_128',
                                                 })

            configure_ipsec_mocs_command.append({'MOC': 'IKEP', 'ID': f'1-2-1-1-{self.current_secpol_id}',
                                                 'localTunnelEndpointDN': dn_ipaddress,
                                                 'connectionEstablishmentMode': establishment_mode,
                                                 'remoteTunnelEndpoint': gnb['IP_ADDR']
                                                 })
            configure_ipsec_mocs_command.append({'MOC': 'SECPOL', 'ID': f'1-2-1-1-{self.current_secpol_id}',
                                                 'ikePDN': f'MRBTS-{self.mrbts_id}/TNLSVC-1/TNL-{tnl_id}/IPAPP-1/IPSECC-1/IKEP-{self.current_secpol_id}',
                                                 'ipSecPDN': f'MRBTS-{self.mrbts_id}/TNLSVC-1/TNL-{tnl_id}/IPAPP-1/IPSECC-1/IPSECP-1',
                                                 'policyOrderNumber': self.current_policy_order_num,
                                                 'trafficSelectorList': [{'localIpAddress': gnb['FAREND_IP'],
                                                                          'localIpPrefixLength': prefix_length,
                                                                          'remoteIpAddress': gnb['IP_ADDR'],
                                                                          'remoteIpPrefixLength': prefix_length
                                                                          }]
                                                 })
            self.current_policy_order_num += 1
            self.current_secpol_id += 1
        return configure_ipsec_mocs_command

    def _add_ipsec_config_vcu_mocs(self, nrdu_moc_and_ip_list, establishment_mode):
        # if real vDU isn't given in connections, it will not be found in vdu_params_provided_in_connections
        # [{'NRDU-1': '172.16.1.1'}, {'NRDU-2': '10.0.1.151'}, {'NRDU-3': '10.0.1.152'}]

        vdu_params_defined_in_connections = self._db._get_prepared_vdu_params_defined_in_connections(nrdu_moc_and_ip_list)
        ipv4_f1c_dn_ipaddress, ipv6_f1c_dn_ipaddress = self._get_ipv4_and_ipv6_address_dn1_for_link_type('f1c', alias=self.alias)

        configure_ipsec_mocs_command = []
        configure_ipsec_mocs_command.append({'MOC': 'IPAPP', 'ID': '1-2-1'})
        configure_ipsec_mocs_command.append({'MOC': 'IPSECC', 'ID': '1-2-1-1',
                                             'authenticationScheme': 'PSK',
                                             'ipSecEnabled': 'true'})
        configure_ipsec_mocs_command.append({'MOC': 'IPSECP', 'ID': '1-2-1-1-1',
                                             'antiReplayWindowSize': 'SIZE_128',
                                             })
        for vdu in vdu_params_defined_in_connections:
            du_id = vdu['moc_id'].split('-')[1]
            dn_ipaddress, tnl_id, prefix_length = self._get_interface_dn_ipaddres_tnl_id_and_prefix_length(vdu['f1c_du_ip_addr'], ipv4_f1c_dn_ipaddress, ipv6_f1c_dn_ipaddress)
            if dn_ipaddress is None:
                continue
            for real_vdus in self._db.real_vdu_list:
                if real_vdus['f1c_du_ip_addr'] == vdu['f1c_du_ip_addr']:
                    real_vdus["policy_order_num"] = self.current_policy_order_num

            configure_ipsec_mocs_command.append({'MOC': 'IKEP', 'ID': f'1-2-1-1-{du_id}',
                                                 'localTunnelEndpointDN': dn_ipaddress,
                                                 'remoteTunnelEndpoint': vdu['f1c_du_ip_addr'],
                                                 'connectionEstablishmentMode': establishment_mode,
                                                 })
            configure_ipsec_mocs_command.append({'MOC': 'SECPOL', 'ID': f'1-2-1-1-{du_id}',
                                                 'ikePDN': f'MRBTS-{self.mrbts_id}/TNLSVC-1/TNL-{tnl_id}/IPAPP-1/IPSECC-1/IKEP-{du_id}',
                                                 'ipSecPDN': f'MRBTS-{self.mrbts_id}/TNLSVC-1/TNL-{tnl_id}/IPAPP-1/IPSECC-1/IPSECP-1',
                                                 'policyOrderNumber': self.current_policy_order_num,
                                                 'trafficSelectorList': [{'localIpAddress': vdu['f1c_cu_ip_addr'],
                                                                          'localIpPrefixLength': prefix_length,
                                                                          'remoteIpAddress': vdu['f1c_du_ip_addr'],
                                                                          'remoteIpPrefixLength': prefix_length
                                                                          }]
                                                 })
            self.current_policy_order_num += 1
            self.current_secpol_id = int(du_id)
        self.current_secpol_id += 1
        return configure_ipsec_mocs_command

